<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Maze Discovery — 24 Bots</title>
<style>
  :root { --bg:#11141a; --fg:#e8ecf3; --acc:#5ad1ff; }
  * { box-sizing: border-box; }
  body {
    margin:0; padding:18px; background:var(--bg); color:var(--fg);
    font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
    display:flex; flex-direction:column; align-items:center; gap:14px;
  }
  h1 { font-size:16px; letter-spacing:.14em; text-transform:uppercase; margin:0; font-weight:600; }
  #hud {
    display:flex; gap:22px; align-items:center; flex-wrap:wrap; justify-content:center;
    background:#181d26; border:1px solid #2a323f; border-radius:8px; padding:10px 16px;
  }
  .stat { display:flex; flex-direction:column; align-items:center; gap:2px; }
  .stat .label { font-size:10px; letter-spacing:.12em; color:#8b97a8; text-transform:uppercase; }
  .stat .value { font-size:20px; color:var(--acc); font-variant-numeric:tabular-nums; }
  button {
    font:inherit; font-size:13px; padding:8px 16px; border-radius:6px; cursor:pointer;
    background:#243040; color:var(--fg); border:1px solid #3a475a;
  }
  button:hover { background:#2f3e52; }
  #maze { border:1px solid #2a323f; border-radius:8px; background:#0c0f14; padding:8px; line-height:0; }
  canvas { display:block; }
  #note { font-size:11px; color:#7f8b9c; max-width:560px; text-align:center; line-height:1.5; }
</style>
</head>
<body>

<h1>Maze Discovery</h1>

<div id="hud">
  <div class="stat"><span class="label">Completed</span><span class="value" id="completed">0 / 24</span></div>
  <div class="stat"><span class="label">Timer (ticks)</span><span class="value" id="timer">0</span></div>
  <div class="stat"><span class="label">Seed</span><span class="value" id="seedout">—</span></div>
  <button id="reset">Reset</button>
</div>

<div id="maze"><canvas id="cv" width="504" height="504"></canvas></div>

<div id="note">24 bots explore blind, one cell per tick, Tremaux/DFS style: each remembers only what it has walked, backtracks out of exhausted branches and never re-enters them. No global pathfinding.</div>

<script>
(function () {
  "use strict";

  var ROWS = 21, COLS = 21, NBOTS = 24, CELL = 24, PAD = 0;
  var MAX_TICKS = 20000;

  // ---------- seeded RNG ----------
  function mulberry32(a) {
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  var DIRS = [
    { k: "n", dr: -1, dc: 0, opp: "s" },
    { k: "e", dr: 0, dc: 1, opp: "w" },
    { k: "s", dr: 1, dc: 0, opp: "n" },
    { k: "w", dr: 0, dc: -1, opp: "e" }
  ];

  // all 24 permutations of 0..3 -> one distinct exploration preference per bot
  function permutations(arr) {
    if (arr.length <= 1) return [arr.slice()];
    var out = [];
    for (var i = 0; i < arr.length; i++) {
      var rest = arr.slice(0, i).concat(arr.slice(i + 1));
      var subs = permutations(rest);
      for (var j = 0; j < subs.length; j++) out.push([arr[i]].concat(subs[j]));
    }
    return out;
  }
  var ORDERS = permutations([0, 1, 2, 3]); // exactly 24

  // ---------- state ----------
  var grid = null;        // grid[r][c] = {n,e,s,w} true === wall
  var bots = [];
  var elapsed = 0;
  var seed = 0;
  var spawn = { r: 0, c: 0 };
  var exitCell = { r: ROWS - 1, c: COLS - 1 };
  var manual = false;     // once tick() is driven externally, stop auto-running

  function idx(r, c) { return r * COLS + c; }
  function inBounds(r, c) { return r >= 0 && r < ROWS && c >= 0 && c < COLS; }

  // ---------- maze generation (recursive backtracker, perfect maze) ----------
  function buildMaze(rnd) {
    var g = [];
    for (var r = 0; r < ROWS; r++) {
      g[r] = [];
      for (var c = 0; c < COLS; c++) g[r][c] = { n: true, e: true, s: true, w: true };
    }
    var seen = new Uint8Array(ROWS * COLS);
    var stack = [{ r: 0, c: 0 }];
    seen[0] = 1;
    while (stack.length) {
      var cur = stack[stack.length - 1];
      var opts = [];
      for (var d = 0; d < 4; d++) {
        var nr = cur.r + DIRS[d].dr, nc = cur.c + DIRS[d].dc;
        if (inBounds(nr, nc) && !seen[idx(nr, nc)]) opts.push(d);
      }
      if (!opts.length) { stack.pop(); continue; }
      var pick = opts[Math.floor(rnd() * opts.length) % opts.length];
      var D = DIRS[pick];
      var tr = cur.r + D.dr, tc = cur.c + D.dc;
      g[cur.r][cur.c][D.k] = false;
      g[tr][tc][D.opp] = false;
      seen[idx(tr, tc)] = 1;
      stack.push({ r: tr, c: tc });
    }
    return g;
  }

  // ---------- bots ----------
  function makeBots() {
    var list = [];
    for (var i = 0; i < NBOTS; i++) {
      var order = ORDERS[i % ORDERS.length].map(function (d) { return DIRS[d]; });
      var b = {
        id: i,
        r: spawn.r, c: spawn.c,
        pr: spawn.r, pc: spawn.c,     // previous cell, for smooth interpolation
        order: order,
        visited: new Set([idx(spawn.r, spawn.c)]),
        deadSet: new Set(),
        stack: [],
        path: [{ r: spawn.r, c: spawn.c }],
        deadEnds: [],
        finishTick: null,
        color: "hsl(" + Math.round((i * 360) / NBOTS) + ",85%,62%)"
      };
      if (spawn.r === exitCell.r && spawn.c === exitCell.c) b.finishTick = 0;
      list.push(b);
    }
    return list;
  }

  function stepBot(b, tickNum) {
    if (b.finishTick !== null) return;
    var w = grid[b.r][b.c];
    var next = null;
    for (var i = 0; i < 4; i++) {
      var D = b.order[i];
      if (w[D.k]) continue;                       // wall: bot learns it by feeling for it
      var nr = b.r + D.dr, nc = b.c + D.dc;
      if (!inBounds(nr, nc)) continue;
      var k = idx(nr, nc);
      if (b.visited.has(k) || b.deadSet.has(k)) continue;
      next = { r: nr, c: nc, k: k };
      break;
    }
    b.pr = b.r; b.pc = b.c;
    if (next) {
      b.stack.push({ r: b.r, c: b.c });
      b.r = next.r; b.c = next.c;
      b.visited.add(next.k);
      b.path.push({ r: b.r, c: b.c });
    } else {
      // exhausted branch -> mark dead in this bot's own memory, back out
      var here = idx(b.r, b.c);
      if (!b.deadSet.has(here)) {
        b.deadSet.add(here);
        b.deadEnds.push({ r: b.r, c: b.c });
      }
      var prev = b.stack.pop();
      if (prev) {
        b.r = prev.r; b.c = prev.c;
        b.path.push({ r: b.r, c: b.c });
      }
    }
    if (b.r === exitCell.r && b.c === exitCell.c) b.finishTick = tickNum;
  }

  function allDone() {
    for (var i = 0; i < bots.length; i++) if (bots[i].finishTick === null) return false;
    return true;
  }
  function completedCount() {
    var n = 0;
    for (var i = 0; i < bots.length; i++) if (bots[i].finishTick !== null) n++;
    return n;
  }

  function tickOnce() {
    if (allDone()) return;               // timer frozen at the last arrival
    if (elapsed >= MAX_TICKS) return;
    elapsed++;
    for (var i = 0; i < bots.length; i++) stepBot(bots[i], elapsed);
  }

  // ---------- reset ----------
  function reset(s) {
    seed = (typeof s === "number" && isFinite(s)) ? (s >>> 0)
         : (Math.floor(Math.random() * 0xffffffff) >>> 0);
    var rnd = mulberry32(seed);
    grid = buildMaze(rnd);
    spawn = { r: 0, c: 0 };
    exitCell = { r: ROWS - 1, c: COLS - 1 };
    bots = makeBots();
    elapsed = 0;
    lastTickTime = now();
    draw();
    updateHud();
  }

  // ---------- rendering ----------
  var cv = document.getElementById("cv");
  var ctx = cv.getContext("2d");
  cv.width = COLS * CELL + PAD * 2;
  cv.height = ROWS * CELL + PAD * 2;

  function now() {
    return (typeof performance !== "undefined" && performance.now) ? performance.now() : Date.now();
  }

  function draw(alpha) {
    var t = (typeof alpha === "number") ? alpha : 1;
    ctx.fillStyle = "#0c0f14";
    ctx.fillRect(0, 0, cv.width, cv.height);

    // exit + spawn markers
    ctx.fillStyle = "rgba(70,220,140,0.30)";
    ctx.fillRect(PAD + exitCell.c * CELL + 2, PAD + exitCell.r * CELL + 2, CELL - 4, CELL - 4);
    ctx.fillStyle = "rgba(120,150,255,0.22)";
    ctx.fillRect(PAD + spawn.c * CELL + 2, PAD + spawn.r * CELL + 2, CELL - 4, CELL - 4);

    // walls
    ctx.strokeStyle = "#9fb0c8";
    ctx.lineWidth = 2;
    ctx.lineCap = "square";
    ctx.beginPath();
    for (var r = 0; r < ROWS; r++) {
      for (var c = 0; c < COLS; c++) {
        var x = PAD + c * CELL, y = PAD + r * CELL, w = grid[r][c];
        if (w.n) { ctx.moveTo(x, y); ctx.lineTo(x + CELL, y); }
        if (w.w) { ctx.moveTo(x, y); ctx.lineTo(x, y + CELL); }
        if (w.s) { ctx.moveTo(x, y + CELL); ctx.lineTo(x + CELL, y + CELL); }
        if (w.e) { ctx.moveTo(x + CELL, y); ctx.lineTo(x + CELL, y + CELL); }
      }
    }
    ctx.stroke();

    // bots (interpolated between previous and current cell, centered in corridor)
    for (var i = 0; i < bots.length; i++) {
      var b = bots[i];
      var rr = b.pr + (b.r - b.pr) * t;
      var cc = b.pc + (b.c - b.pc) * t;
      var px = PAD + cc * CELL + CELL / 2;
      var py = PAD + rr * CELL + CELL / 2;
      ctx.beginPath();
      ctx.arc(px, py, CELL * 0.24, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.globalAlpha = b.finishTick !== null ? 0.55 : 1;
      ctx.fill();
      ctx.globalAlpha = 1;
    }
  }

  function updateHud() {
    document.getElementById("completed").textContent = completedCount() + " / " + NBOTS;
    document.getElementById("timer").textContent = String(elapsed);
    document.getElementById("seedout").textContent = String(seed);
  }

  // ---------- animation / auto-run ----------
  var TICK_MS = 70;
  var lastTickTime = now();

  function frame() {
    var t = now();
    if (!manual) {
      var guard = 0;
      while (t - lastTickTime >= TICK_MS && guard < 240) {
        if (allDone()) { lastTickTime = t; break; }
        tickOnce();
        lastTickTime += TICK_MS;
        guard++;
      }
      if (t - lastTickTime > TICK_MS * 8) lastTickTime = t;
    }
    var alpha = manual ? 1 : Math.max(0, Math.min(1, (t - lastTickTime) / TICK_MS));
    if (allDone()) alpha = 1;
    draw(alpha);
    updateHud();
    requestAnimationFrame(frame);
  }

  document.getElementById("reset").addEventListener("click", function () { reset(); });

  // ---------- scripting API ----------
  window.game = {
    tick: function (n) {
      manual = true;                 // hand control to the script driver
      var count = (n === undefined || n === null) ? 1 : Math.floor(n);
      if (!isFinite(count) || count < 0) count = 0;
      for (var i = 0; i < count; i++) tickOnce();
      lastTickTime = now();
      draw(1);
      updateHud();
      return elapsed;
    },
    reset: function (s) { reset(s); return elapsed; },
    get elapsed() { return elapsed; },
    get size() { return { rows: ROWS, cols: COLS }; },
    get spawn() { return { r: spawn.r, c: spawn.c }; },
    get exit() { return { r: exitCell.r, c: exitCell.c }; },
    get seed() { return seed; },
    get bots() { return bots; },
    get completed() { return completedCount(); },
    walls: function (r, c) {
      if (!inBounds(r, c)) return null;
      var w = grid[r][c];
      return { n: !!w.n, e: !!w.e, s: !!w.s, w: !!w.w };
    }
  };

  reset(1234);
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
